package org.xar.ck3.control.nativebridge.capabilities.army;

import static org.xar.ck3.control.nativebridge.capabilities.army.ArmyOwnedJson.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Set;

/** Full natural parent-phase lineage, preserving nullable date/session reads and raw roster occurrences. */
public final class ArmyNaturalPhases {
    private ArmyNaturalPhases() { }
    public record Token(BigInteger clock,BigInteger sequence,Long thread){public ObjectNode toJson(){ObjectNode o=obj().put("clock_identity",clock).put("sequence",sequence);put(o,"thread_id",thread);return o;}}
    public enum Phase{PRE_DATE("pre_date",0x2A99DA0L),POST_DATE("post_date",0x2A9A570L);final String wire;final long entry;Phase(String wire,long entry){this.wire=wire;this.entry=entry;}}
    public enum RosterBoundary{PARENT_ENTRY("parent_entry"),PRE_DATE_PREFIX_RETURN("pre_date_prefix_return");final String wire;RosterBoundary(String wire){this.wire=wire;}}
    public record Roster(RosterBoundary boundary,BigInteger captureRva,Token capture,BigInteger begin,BigInteger end,Integer count,boolean complete,List<Long> orderedFullIds){public Roster{orderedFullIds=List.copyOf(orderedFullIds);}ObjectNode toJson(){ObjectNode o=obj().put("boundary",boundary.wire).put("capture_rva",captureRva);o.set("capture_event",capture.toJson());put(o,"begin_identity",begin);put(o,"end_identity",end);put(o,"count",count);o.put("complete",complete);ArrayNode ids=o.putArray("ordered_full_ids");orderedFullIds.forEach(ids::add);return o;}}
    public record Scope(boolean observed,Phase phase,BigInteger actualEntry,BigInteger callerReturn,BigInteger primaryManager,BigInteger secondaryManager,BigInteger gameState,BigInteger session,Token entry,BigInteger date,BigInteger prefixDate,Long absoluteDay,Integer entryC0,Integer savedC0,Boolean admittedMask,BigInteger savedRva,Token savedEvent,Roster roster){ObjectNode toJson(){ObjectNode o=obj().put("observed",observed).put("phase",phase.wire).put("actual_entry_rva",actualEntry).put("caller_return_rva",callerReturn).put("primary_manager_identity",primaryManager).put("secondary_manager_identity",secondaryManager).put("game_state_identity",gameState);put(o,"session_identity",session);o.set("entry_event",entry.toJson());put(o,"date_raw",date);put(o,"prefix_date_raw",prefixDate);put(o,"absolute_day_raw",absoluteDay);put(o,"entry_c0_raw",entryC0);put(o,"saved_c0_raw",savedC0);put(o,"saved_mask02_admitted",admittedMask);o.put("saved_c0_observed_rva",savedRva);o.set("saved_c0_event",savedEvent.toJson());o.set("original_army_roster",roster.toJson());return o;}}
    public record Record(Scope scope,boolean originalCalled,boolean originalReturned,BigInteger rawReturn,Token returned,BigInteger returnedDate,Long returnedDay,Integer returnedC0,Boolean sameOrder){ObjectNode toJson(){ObjectNode o=obj();o.set("scope",scope.toJson());o.put("original_called",originalCalled).put("original_returned",originalReturned).put("raw_return_bits",rawReturn);o.set("returned_event",returned.toJson());put(o,"returned_date_raw",returnedDate);put(o,"returned_absolute_day_raw",returnedDay);put(o,"returned_c0_raw",returnedC0);put(o,"same_clock_thread_order",sameOrder);return o;}}
    public record Journal(long subjectFullId,List<Record> records){public Journal{records=List.copyOf(records);}public ObjectNode toJson(){ObjectNode o=obj().put("schema_version",1).put("source","owned_native_natural_army_phase_records").put("membership_basis","captured_parent_roster_full_CArmy_ID_occurrences").put("subject_full_carmy_id_u32",subjectFullId);ArrayNode a=o.putArray("records");records.forEach(record->a.add(record.toJson()));return o;}}
    static Token token(JsonNode n){tokenShape(n);return new Token(u64(n.get("clock_identity")),u64(n.get("sequence")),nu32(n.get("thread_id")));}
    static boolean sameThread(Token a,Token z){return a.clock.signum()!=0&&a.clock.equals(z.clock)&&a.sequence.signum()>0&&z.sequence.signum()>0&&a.thread!=null&&z.thread!=null&&a.thread>0&&z.thread>0&&a.thread.equals(z.thread);}
    static boolean later(Token a,Token z){return sameThread(a,z)&&a.sequence.compareTo(z.sequence)<0;}
    private static void inside(Token entry,Token observed,Token returned,String label){need(later(entry,observed),label+" lacks owning entry clock/thread");if(sameThread(observed,returned))need(observed.sequence.compareTo(returned.sequence)<0,label+" does not precede original return");}
    private static Phase phase(JsonNode value){String wire=text(value);for(Phase phase:Phase.values())if(phase.wire.equals(wire))return phase;throw new IllegalArgumentException("owned Army unknown natural phase");}
    private static RosterBoundary boundary(JsonNode value){String wire=text(value);for(RosterBoundary boundary:RosterBoundary.values())if(boundary.wire.equals(wire))return boundary;throw new IllegalArgumentException("owned Army unknown roster capture boundary");}
    static Scope scope(JsonNode n){JsonNode r=n.get("original_army_roster");List<Long> ids=new ArrayList<>();r.get("ordered_full_ids").forEach(id->ids.add(u32(id)));Roster roster=new Roster(boundary(r.get("boundary")),u64(r.get("capture_rva")),token(r.get("capture_event")),nu64(r.get("begin_identity")),nu64(r.get("end_identity")),ni32(r.get("count")),bool(r.get("complete")),ids);return new Scope(bool(n.get("observed")),phase(n.get("phase")),u64(n.get("actual_entry_rva")),u64(n.get("caller_return_rva")),u64(n.get("primary_manager_identity")),u64(n.get("secondary_manager_identity")),u64(n.get("game_state_identity")),nu64(n.get("session_identity")),token(n.get("entry_event")),nu64(n.get("date_raw")),nu64(n.get("prefix_date_raw")),nu32(n.get("absolute_day_raw")),nu8(n.get("entry_c0_raw")),nu8(n.get("saved_c0_raw")),maybeBool(n.get("saved_mask02_admitted")),u64(n.get("saved_c0_observed_rva")),token(n.get("saved_c0_event")),roster);}
    public static Journal normalize(JsonNode n,Integer expectedArmy){if(n==null||n.isNull())return null;ArmyObservedSchema.family(ArmyObservedSchema.Family.PHASE,n,expectedArmy);long full=Integer.toUnsignedLong(expectedArmy);need(text(n.get("membership_basis")).equals("captured_parent_roster_full_CArmy_ID_occurrences")&&u32(n.get("subject_full_carmy_id_u32"))==full,"phase subject/full-generation membership basis differs");ArrayNode events=array(n.get("records"));need(events.size()<=64,"natural phase journal exceeds 64 records");List<Record> records=new ArrayList<>();for(JsonNode event:events){Scope scope=scope(event.get("scope"));boolean called=bool(event.get("original_called")),returned=bool(event.get("original_returned"));Token end=token(event.get("returned_event"));BigInteger date=nu64(event.get("returned_date_raw"));Long day=nu32(event.get("returned_absolute_day_raw"));Integer c0=nu8(event.get("returned_c0_raw"));Boolean order=maybeBool(event.get("same_clock_thread_order"));need(scope.observed&&called&&returned,"published phase lacks original entry/return");need(scope.actualEntry.equals(BigInteger.valueOf(scope.phase.entry)),"natural phase source entry differs");need(scope.primaryManager.signum()>0&&scope.secondaryManager.equals(scope.primaryManager.add(BigInteger.valueOf(8))),"natural phase primary/secondary manager pair differs");boolean available=scope.entry.clock.signum()!=0&&end.clock.signum()!=0&&scope.entry.thread!=null&&end.thread!=null;Boolean actualOrder=available?later(scope.entry,end):null;need(Objects.equals(order,actualOrder),"phase order claim differs from copied tokens");if(scope.gameState.signum()==0)need(scope.date==null&&scope.absoluteDay==null&&scope.entryC0==null&&date==null&&day==null&&c0==null,"absent GameState supplied date/calendar samples");roster(scope,end,full);saved(scope,end);records.add(new Record(scope,called,returned,u64(event.get("raw_return_bits")),end,date,day,c0,order));}return new Journal(full,records);}
    private static void roster(Scope scope,Token returned,long full){Roster r=scope.roster;need(r.orderedFullIds.contains(full),"captured roster loses subject full generation");if(r.boundary==RosterBoundary.PARENT_ENTRY){need(r.captureRva.equals(scope.actualEntry)&&r.capture.equals(scope.entry)&&scope.prefixDate==null,"parent-entry roster boundary/date was replaced");}else{need(scope.phase==Phase.PRE_DATE&&r.captureRva.equals(BigInteger.valueOf(0x2A99E76L)),"prefix roster lacks literal pre-date return");inside(scope.entry,r.capture,returned,"prefix roster");}if(r.count!=null)need(r.count>=0&&r.orderedFullIds.size()<=r.count,"roster copied count exceeds native extent");if(r.begin!=null&&r.end!=null&&r.count!=null)need(r.begin.add(BigInteger.valueOf(r.count).multiply(BigInteger.valueOf(4))).equals(r.end)&&r.end.compareTo(U64)<=0,"roster native DWORD bounds differ");if(r.complete)need(r.count!=null&&r.count==r.orderedFullIds.size()&&r.count<=65536&&r.begin!=null&&r.end!=null&&(r.count==0||r.begin.signum()!=0),"complete roster loses full native extent");}
    private static void saved(Scope scope,Token returned){if(scope.phase==Phase.PRE_DATE||scope.admittedMask==null){need(scope.savedC0==null&&scope.admittedMask==null&&scope.savedRva.signum()==0&&scope.savedEvent.equals(new Token(BigInteger.ZERO,BigInteger.ZERO,null)),"unobserved saved C0 acquired source evidence");return;}need(scope.savedRva.bitLength()<=63,"saved C0 source boundary differs");long rva=scope.savedRva.longValueExact();Set<Long> mask=Set.of(0x2A9A672L,0x2A9A67DL,0x2A9A8E2L,0x2A9A8EAL);need(rva==0x2A9A65DL||mask.contains(rva),"saved C0 source boundary differs");inside(scope.entry,scope.savedEvent,returned,"saved C0");if(rva==0x2A9A65DL)need(scope.savedC0!=null,"full C0 save supplies only masked bit");if(rva==0x2A9A672L||rva==0x2A9A8E2L)need(Boolean.TRUE.equals(scope.admittedMask),"conditional child lost admitted saved mask");if(scope.savedC0!=null)need(scope.admittedMask==((scope.savedC0&2)!=0),"full saved C0 and mask disagree");}
}
